/**
 * Origin allowlist check used by both cors() and the auth-handler raw
 * Response patch. TRUSTED_ORIGINS is the compile-time allowlist
 * (localhost dev defaults + anything the project declared); a deployed
 * worker also auto-trusts its own BETTER_AUTH_URL so prod requests from
 * the configured base origin are accepted without an explicit
 * trustedOrigins entry. EXTRA_APP_HOSTS (comma-separated hostnames) lets
 * preview/dev deploys extend the allowlist at deploy time without a
 * recompile — any origin whose hostname appears there is trusted, which
 * matches how the apps hostname middleware treats the same env var.
 */
function isTrustedOrigin(origin: string, c: { env?: any } | undefined): boolean {
  if (TRUSTED_ORIGINS.includes(origin as (typeof TRUSTED_ORIGINS)[number])) return true;
  const baseUrl: string | undefined = c?.env?.BETTER_AUTH_URL;
  if (baseUrl && origin === baseUrl) return true;
  const extra: string | undefined = c?.env?.EXTRA_APP_HOSTS;
  if (extra) {
    try {
      const url = new URL(origin);
      const host = url.hostname;
      // A hostname-only entry is trusted as an https origin; plain http is
      // accepted on loopback only (local dev). Otherwise an attacker on the
      // same hostname over http could ride the cookie (pentest 2026-10-23).
      const loopback = host === 'localhost' || host === '127.0.0.1' || host === '[::1]' || host.endsWith('.localhost');
      if (url.protocol !== 'https:' && !loopback) return false;
      const list = extra.split(',').map((s: string) => s.trim()).filter(Boolean);
      if (list.includes(host)) return true;
    } catch {}
  }
  return false;
}

