  // scope tokens, ws tickets, and the sessionless scope-mint inputs.
  'sessionToken', 'session_token', 'eventSessionToken', 'scopeJwt', 'scopeToken',
  'wsTicket', 'ws_ticket', 'ticket', 'inviteToken', 'invite_token',
  'jwt', 'bearer', 'signature', 'privateKey', 'private_key',
