// CSRF guard for cookie-backed mutating requests.
//
// CORS is not CSRF protection: a malicious site can still trigger a
// cross-site form POST or fetch with ambient cookies attached, even if the
// browser later withholds the response from JS. The risk shape here is
// specifically "cookie-authenticated mutation from an untrusted origin".
//
// So:
//   - Bearer/API-key style clients should use Authorization and skip this gate.
//   - Cookie-backed POST/PUT/PATCH/DELETE requests must come from a trusted
//     Origin (or Referer fallback) and must not advertise
//     Sec-Fetch-Site: cross-site.
//   - Clients that want machine-to-machine writes should authenticate with an
//     explicit bearer, not a browser cookie jar.
app.use('*', async (c, next) => {
  const method = c.req.method;
  if (method !== 'POST' && method !== 'PUT' && method !== 'PATCH' && method !== 'DELETE') {
    return next();
  }

  const hasAuthorization = Boolean(c.req.header('Authorization'));
  const hasCookie = Boolean(c.req.header('Cookie'));
  if (hasAuthorization || !hasCookie) {
    return next();
  }

  const origin = c.req.header('Origin');
  const referer = c.req.header('Referer');
  const fetchSite = c.req.header('Sec-Fetch-Site');
  const requestOrigin = origin
    ?? (() => {
      try {
        return referer ? new URL(referer).origin : null;
      } catch {
        return null;
      }
    })();

  if (!requestOrigin || !isTrustedOrigin(requestOrigin, c) || fetchSite === 'cross-site') {
    return problemJson(c, {
      error: 'Cross-site cookie-backed mutation blocked',
      code: 'CSRF_ORIGIN_REJECTED',
      layer: 'auth',
      hint: 'Send mutating browser requests from a trusted origin, or use Authorization bearer tokens for non-browser clients.',
    }, 403);
  }

  return next();
});

