// Global error handler — logs with the request ID for log↔response
// correlation, and includes the same ID in the 500 body so an oncall
// engineer with the response can find the matching log line.
//
// Production default is a GENERIC body: { error, code, layer, hint,
// requestId } — no error message, class name, cause, or stack frames.
// The full detail (message, cause chain, stack) is always logged via
// console.error. Set `EXPOSE_ERROR_STACK=1` (env / Wrangler var) to
// surface the verbose body — error message, class name, cause-chain
// message, sanitized top frames, and the full stack — useful in dev /
// staging, off in prod (an uncaught error's message can carry SQL,
// paths, or secrets).
//
// Body still carries `code` + `layer` so the request-context middleware
// augments it with method/url/body just like every other structured
// error — agent-friendly even on uncaught throws.
app.onError((err: any, c) => {
  // ActionError safety-net: actions mounted off their feature prefix (e.g.
  // standalone at /me/...) and app.use('*') middleware throw outside any
  // per-handler ActionError try/catch. Map by name to the declared status so
  // "throw ActionError for a clean 4xx" holds regardless of throw site. (Both
  // onError registrations carry this — Hono keeps the last-registered, but
  // mapping in both is order-independent and survives a future reorder.)
  if (err?.name === 'ActionError') {
    return problemJson(c, {
      error: err.message,
      code: err.code,
      layer: 'action',
      ...(err.details ? { details: err.details } : {}),
      ...(err.hint ? { hint: err.hint } : {}),
    }, err.statusCode || 400);
  }
  const requestId = c.get('requestId') ?? 'unknown';
  // Bound values never reach the log or the opt-in body (lib/errors redactError).
  err = redactError(err);
  const isErr = err instanceof Error;
  const name = isErr ? err.name : 'Error';
  const message = isErr ? err.message : (typeof err === 'string' ? err : 'unknown error');
  const cause = err?.cause;
  const causeMessage = cause instanceof Error
    ? cause.message
    : (cause != null && typeof cause !== 'object' ? String(cause) : undefined);
  const stack = isErr ? err.stack : undefined;

  // Full detail ALWAYS goes to the server log — the response body only
  // ever gets it under the explicit EXPOSE_ERROR_STACK opt-in below.
  console.error(JSON.stringify({
    level: 'error',
    requestId,
    method: c.req.method,
    path: new URL(c.req.url).pathname,
    name,
    // Driver codes (SQLITE_CONSTRAINT_UNIQUE, 23505) survive redaction.
    code: err?.code,
    causeCode: err?.cause?.code,
    message,
    causeMessage,
    stack,
  }));

  // Verbose-body exposure is opt-in via EXPOSE_ERROR_STACK (c.env on
  // Workers, process.env on Node/Bun) — read by the one shared check in
  // lib/errors (isErrorStackExposed), the same one exposeErrorReason uses.
  const exposeStack = isErrorStackExposed(c);

  if (exposeStack) {
    // Dev / staging opt-in: forward the underlying error. Top frames get
    // absolute file paths stripped so the worker bundle's on-disk layout
    // doesn't leak even here.
    const topFrames = stack
      ? stack.split('\n').slice(1, 4)
          .map((l: string) => l.replace(/\(?(?:file:\/\/)?\/[^):\s]+?([^/():\s]+:\d+(?::\d+)?)\)?/g, '($1)').trim())
          .filter(Boolean)
      : undefined;
    return problemJson(c, {
      error: message || 'Internal server error',
      code: 'INTERNAL_ERROR',
      layer: 'database',
      details: {
        name,
        ...(causeMessage ? { cause: causeMessage } : {}),
        ...(topFrames && topFrames.length ? { frames: topFrames } : {}),
        ...(stack ? { stack } : {}),
      },
      hint: 'Uncaught error during request handling. Look up the requestId in server logs for the full stack trace. (Verbose body: EXPOSE_ERROR_STACK is set — unset it in production.)',
      requestId,
    }, 500);
  }

  // Production default: generic body. No message, class name, cause, or
  // stack frames — those live in the console.error line above, keyed by
  // requestId.
  return problemJson(c, {
    error: 'Internal server error',
    code: 'INTERNAL_ERROR',
    layer: 'database',
    hint: 'Uncaught error during request handling. Look up the requestId in server logs for the full stack trace, or set EXPOSE_ERROR_STACK=1 (dev/staging only) to include error details inline.',
    requestId,
  }, 500);
});

