  if (__ikey.length > 255) {
    return problemJson(c, { error: 'Idempotency-Key must be 255 characters or fewer', code: 'VALIDATION_INVALID_INPUT', layer: 'validation' }, 400);
  }
  const __idb = c.get('db');
  if (!__idb) return next();
  const __ipath = new URL(c.req.url).pathname;
  // Principal fingerprint — session user first, delegated principal second,
  // scope principal third. Scope lanes key on subjectId ?? id — the SAME
  // canonical identity the scope mint stamps as its `sub` claim — because
  // multiple distinct subjects (supplied-subject mints) can share one scope
  // INSTANCE id; keying on the instance alone would give subject B full
  // replay of subject A's cached body under a leaked/guessed key.
  const __ictx = c.get('ctx') as any;
