  if (__ictx?.link?.id) {
    // FGA share-link principal: keyed per link, never shared with the
    // restricted link's signed-in user or the link's scope instance.
    __iprincipal = 'link:' + __ictx.link.id;
  } else if (__ictx?.userId) {
    __iprincipal = 'user:' + __ictx.userId;
  } else if (__ictx?.principal?.actor?.id) {
    // Delegated-principal lane (authMethod 'principal') — machine callers are
    // exactly the ones most likely to send Idempotency-Key on writes.
    __iprincipal = 'principal:' + __ictx.principal.type + ':' + __ictx.principal.actor.id;
  } else if (__ictx?.scope && typeof __ictx.scope === 'object') {
    const __iscopeParts = Object.keys(__ictx.scope).sort().map((k) => k + ':' + ((__ictx.scope[k] && (__ictx.scope[k].subjectId ?? __ictx.scope[k].id)) ?? ''));
    if (__iscopeParts.length > 0) __iprincipal = 'scope:' + __iscopeParts.join(',');
  }
